<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Detalle de arqueo</title><style>body{font:15px Arial;background:#f2f5fa;color:#173354}.wrap{max-width:900px;margin:35px auto;padding:20px}.panel{background:white;padding:25px;border-radius:12px;margin:20px 0}table{width:100%;border-collapse:collapse}td,th{padding:10px;border-bottom:1px solid #e0e6ee;text-align:left}h1{color:#10345c}</style></head><body><main class="wrap"><p><a href="{{route('receptor.arqueos.index')}}">← Mis arqueos</a></p><h1>Arqueo {{ $arqueo->numero_arqueo }}</h1><div class="panel"><p><strong>Agencia:</strong> {{ $arqueo->agencia_nombre_historico }}</p><p><strong>Ventanilla:</strong> {{ $arqueo->ventanilla_codigo_historico }}</p><p><strong>Receptor:</strong> {{ $arqueo->receptor_nombre_historico }}</p><p><strong>Turno:</strong> {{ $arqueo->turno_nombre_historico }}</p><p><strong>Fecha:</strong> {{ $arqueo->fecha_operativa?->format('d/m/Y') }}</p><p><strong>Estado:</strong> {{ $arqueo->estado }}</p><p><strong>Integridad de firma:</strong> {{ $firmaValida ? 'VERIFICADA' : 'NO VERIFICADA' }}</p></div><div class="panel"><h2>Denominaciones</h2><table><tr><th>Tipo</th><th>Denominación</th><th>Cantidad</th><th>Subtotal</th></tr>@foreach($arqueo->detalles as $d)<tr><td>{{ $d->tipo }}</td><td>Q {{number_format((float)$d->denominacion,2)}}</td><td>{{ $d->cantidad }}</td><td>Q {{number_format((float)$d->subtotal,2)}}</td></tr>@endforeach</table></div><div class="panel"><p><strong>Total billetes:</strong> Q {{number_format((float)$arqueo->total_billetes,2)}}</p><p><strong>Total monedas:</strong> Q {{number_format((float)$arqueo->total_monedas,2)}}</p><p><strong>Total arqueado:</strong> Q {{number_format((float)$arqueo->total_arqueado,2)}}</p><p><strong>Total corte:</strong> Q {{number_format((float)$arqueo->total_corte,2)}}</p><p><strong>Diferencia:</strong> Q {{number_format((float)$arqueo->diferencia,2)}}</p><p><strong>Justificación:</strong> {{ $arqueo->justificacion_diferencia ?: 'No aplica' }}</p><p><strong>Observaciones:</strong> {{ $arqueo->observaciones ?: 'Sin observaciones' }}</p></div></main></body></html>